const SIZES = {"rules":14664915,"creatures":25492556};
const groupOf = (p) => (p.startsWith('data/text/creatures/') ? 'creatures' : 'rules');
const CORE_CACHE = 'pf2e-core';
const TEXT_CACHE = 'pf2e-text';

const scope = new URL(self.registration.scope);
const rel = (url) => { const u = new URL(url); return u.origin === scope.origin && u.pathname.startsWith(scope.pathname) ? u.pathname.slice(scope.pathname.length) : null; };
const keyFor = (path, hash) => new URL(path + '?v=' + hash, scope).href;

const hex = (buf) => Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, '0')).join('');
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchInto(cache, path, hash) {
  const key = keyFor(path, hash);
  if (await cache.match(key)) return false;
  // While a new version is being published the server can briefly still hand out an old copy of a file.
  // Keep a file only when its content matches the hash this version expects; otherwise try again a little
  // later, and if it still doesn't match, give up so the update is retried on the next check.
  for (let attempt = 0; ; attempt++) {
    const url = new URL(path, scope).href + (attempt ? '?r=' + Date.now() : '');
    const res = await fetch(url, { cache: 'reload', credentials: 'same-origin' });
    if (!res.ok) throw new Error(path + ': ' + res.status);
    if (!self.crypto || !crypto.subtle) { await cache.put(key, res); return true; }
    const body = await res.clone().arrayBuffer();
    if (hex(await crypto.subtle.digest('SHA-256', body)).slice(0, 10) === hash) { await cache.put(key, res); return true; }
    if (attempt >= 2) throw new Error(path + ': the server has a different version of this file');
    await wait(4000);
  }
}

self.addEventListener('install', (e) => {
  // Only changed files are downloaded: unchanged ones are already in the cache under the same hash.
  e.waitUntil(caches.open(CORE_CACHE).then((c) => Promise.all(Object.entries(CORE).map(([p, h]) => fetchInto(c, p, h)))));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keep = (cacheName, list) => caches.open(cacheName).then(async (c) => {
      const want = new Set(Object.entries(list).map(([p, h]) => keyFor(p, h)));
      for (const req of await c.keys()) if (!want.has(req.url)) await c.delete(req);
    });
    await keep(CORE_CACHE, CORE);
    await keep(TEXT_CACHE, TEXT);
    for (const k of await caches.keys()) if (![CORE_CACHE, TEXT_CACHE].includes(k)) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  let path = rel(req.url);
  if (path === null || path.startsWith('api/')) return; // other sites and the accounts API: straight to the network
  if (req.mode === 'navigate' && (path === '' || path.endsWith('/'))) path += 'index.html';
  if (CORE[path]) {
    e.respondWith(caches.open(CORE_CACHE).then((c) => c.match(keyFor(path, CORE[path]))).then((hit) => hit || fetch(req)));
  } else if (TEXT[path]) {
    e.respondWith(caches.open(TEXT_CACHE).then(async (c) => {
      const key = keyFor(path, TEXT[path]);
      const hit = await c.match(key);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) c.put(key, res.clone());
      return res;
    }));
  }
});

self.addEventListener('message', (e) => {
  const msg = e.data || {};
  const reply = (data) => e.source && e.source.postMessage(data);
  if (msg.type === 'skip-waiting') self.skipWaiting();
  else if (msg.type === 'status') {
    e.waitUntil(caches.open(TEXT_CACHE).then(async (c) => {
      const have = new Set((await c.keys()).map((r) => r.url));
      const all = Object.entries(TEXT);
      const count = (g, saved) => all.filter(([p, h]) => groupOf(p) === g && (!saved || have.has(keyFor(p, h)))).length;
      reply({ type: 'status', version: VERSION, text: count('rules', true), textTotal: count('rules'),
        creatures: count('creatures', true), creaturesTotal: count('creatures'), sizes: SIZES });
    }));
  } else if (msg.type === 'download-text') {
    e.waitUntil(caches.open(TEXT_CACHE).then(async (c) => {
      const group = msg.group || 'rules';
      const all = Object.entries(TEXT).filter(([p]) => groupOf(p) === group);
      let done = 0, failed = 0;
      const queue = all.slice();
      const worker = async () => { for (let it; (it = queue.shift());) { try { await fetchInto(c, it[0], it[1]); } catch (err) { failed++; } done++; if (done % 5 === 0 || done === all.length) reply({ type: 'progress', done, total: all.length, failed }); } };
      await Promise.all([worker(), worker(), worker(), worker()]);
      reply({ type: 'downloaded', done, total: all.length, failed });
    }));
  }
});
